import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Tracking Data Availability of a Ceph Cluster","description":"","frontmatter":{"title":"Tracking Data Availability of a Ceph Cluster","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph","OSD","数据可用性","存储监控","SLA"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Tracking_Data_Availability_of_a_Ceph_Cluster.md","filePath":"posts/2026/Tracking_Data_Availability_of_a_Ceph_Cluster.md","lastUpdated":1780459816000}'),i={name:"posts/2026/Tracking_Data_Availability_of_a_Ceph_Cluster.md"};function r(n,a,s,d,h,p){return t(),o("div",null,[...a[0]||(a[0]=[l('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲由 Shraddha 主讲，她与 Naveen 同属 Neha 领导下的 RADOS 团队。演讲主题是 Ceph 集群的数据可用性追踪（Data Availability Tracking）功能，涵盖功能背景、实现原理、配置选项及未来规划。</p><h2 id="为什么需要这个功能" tabindex="-1">为什么需要这个功能 <a class="header-anchor" href="#为什么需要这个功能" aria-label="Permalink to &quot;为什么需要这个功能&quot;">​</a></h2><p>目前，用户想了解集群可用性时，通常执行 <code>ceph status</code> 或 <code>ceph health detail</code>，但这只能获取集群的<strong>瞬时状态</strong>（point-in-time snapshot），无法反映过去一个月乃至一年内集群的整体表现。</p><p>虽然可以将 <code>ceph status</code> 输出接入 telemetry，再通过 Prometheus 或 Grafana 可视化，但这需要大量额外工具链，并非内置能力。</p><p>更重要的是，集群健康状态与用户真正关心的问题并不完全一致。用户更关心的是：<strong>我的读写请求能否被可靠地处理？</strong> 为此，团队在 Reef 版本发布时进行了一次调查，59 位架构师和开发者参与，多数人表示：<strong>能够以良好性能可靠地提供 IO 服务</strong>，才是他们对集群可用性的定义。</p><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>该功能引入了一套机制，用于<strong>随时间追踪数据可用性</strong>，区别于传统的集群整体可用性概念。</p><p>核心特性：</p><ul><li>默认以 <strong>1 秒</strong>为采样间隔（cadence）持续追踪</li><li>从 <strong>Tentacle</strong> 版本起提供，当前为 <strong>Tech Preview</strong> 状态</li><li>新增命令：<code>ceph osd pool availability status</code></li></ul><p>命令输出中，每一行对应一个 pool，包含以下字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>uptime</td><td>自追踪开始以来，pool 处于可用状态的累计时长</td></tr><tr><td>downtime</td><td>pool 处于不可用状态的累计时长</td></tr><tr><td>number of failures</td><td>工具捕获到的可用性故障次数</td></tr><tr><td>MTBF</td><td>平均故障间隔时间（Mean Time Between Failures）</td></tr><tr><td>MTTR</td><td>平均恢复时间（Mean Time To Recover）</td></tr><tr><td>score</td><td>可用性评分（nines 数量）</td></tr><tr><td>当前状态</td><td>pool 当前是否可用</td></tr></tbody></table><p><strong>示例说明</strong>：若工具运行了 60 分钟，其中 20 分钟为 downtime（无论是一次连续故障还是多次短暂故障），则 uptime 为 40 分钟，downtime 为 20 分钟。</p><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><h3 id="可用性的定义" tabindex="-1">可用性的定义 <a class="header-anchor" href="#可用性的定义" aria-label="Permalink to &quot;可用性的定义&quot;">​</a></h3><ul><li><strong>可用（Available）</strong>：pool 中所有 PG 均处于 active 状态</li><li><strong>不可用（Unavailable）</strong>：只要有一个或多个 PG 处于非 active 或 stale 状态；或者即使所有 PG 均为 active，但存在任意一个 unfound object，该 pool 也被视为不可用，直到 DBA 将这些对象标记为 unfound 或采取类似处理</li></ul><h3 id="状态转换逻辑" tabindex="-1">状态转换逻辑 <a class="header-anchor" href="#状态转换逻辑" aria-label="Permalink to &quot;状态转换逻辑&quot;">​</a></h3><p>每次采样时，系统对比前一状态（previous state）与当前状态（current state）：</p><p>| 前一状态 | 当前状态 | 时间计入 | |----------|----------| | 可用 | uptime | | 不可用 | 可用 | uptime（认为故障刚结束） | | 可用 | 不可用 | uptime（认为故障刚开始），同时 failures +1 | | 不可用 | 不可用 | downtime |</p><h3 id="数据存储与计算" tabindex="-1">数据存储与计算 <a class="header-anchor" href="#数据存储与计算" aria-label="Permalink to &quot;数据存储与计算&quot;">​</a></h3><ul><li>uptime、downtime、failures 数量及当前可用状态均持久化存储在 MON 中</li><li>MTBF 和 MTTR 在用户查询时实时计算，不持久化存储： <ul><li>MTBF = uptime / number of failures（若 failures 为 0，则 MTBF = 1）</li><li>MTTR = downtime / number of failures</li></ul></li><li><strong>可用性评分（score）</strong> = MTBF / (MTBF + MTTR) <ul><li>score = 0：集群完全不可用，需要资深管理员介入</li><li>score = 1：从未发生故障，运行良好</li></ul></li></ul><h2 id="配置选项" tabindex="-1">配置选项 <a class="header-anchor" href="#配置选项" aria-label="Permalink to &quot;配置选项&quot;">​</a></h2><h3 id="_1-启用-禁用功能" tabindex="-1">1. 启用/禁用功能 <a class="header-anchor" href="#_1-启用-禁用功能" aria-label="Permalink to &quot;1. 启用/禁用功能&quot;">​</a></h3><p>由于是 Tech Preview，默认<strong>禁用</strong>。启用命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ceph config set mon enable_availability_tracking true</span></span></code></pre></div><p>建议：在预期维护窗口（planned downtime）期间，应先禁用该功能，维护完成后再重新启用，避免计划内停机影响 SLA 统计。该配置支持<strong>运行时修改</strong>，无需重启。</p><h3 id="_2-调整采样间隔-cadence" tabindex="-1">2. 调整采样间隔（cadence） <a class="header-anchor" href="#_2-调整采样间隔-cadence" aria-label="Permalink to &quot;2. 调整采样间隔（cadence）&quot;">​</a></h3><p>不同集群对采样精度的需求不同，可自定义间隔。默认值为 1 秒，从 Tentacle 首个版本起支持。</p><p>注意：由于依赖 Paxos，该值不能小于 Paxos 的 propose interval；且功能关闭时无法修改。</p><h3 id="_3-清除单个-pool-的可用性统计" tabindex="-1">3. 清除单个 pool 的可用性统计 <a class="header-anchor" href="#_3-清除单个-pool-的可用性统计" aria-label="Permalink to &quot;3. 清除单个 pool 的可用性统计&quot;">​</a></h3><p>若某 pool 发生了预期内的异常（如计划停机 3 小时），可清除该 pool 的历史统计，避免影响整体 SLA 评估：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ceph osd pool clear-availability-stats &lt;pool-name&gt;</span></span></code></pre></div><p>执行后，uptime、downtime 等所有数值归零。功能关闭时不可操作。</p><h3 id="_4-json-格式输出" tabindex="-1">4. JSON 格式输出 <a class="header-anchor" href="#_4-json-格式输出" aria-label="Permalink to &quot;4. JSON 格式输出&quot;">​</a></h3><p>随着时间推移，人类可读格式（如&quot;30 天&quot;）精度不足。可使用 <code>--format json-pretty</code> 获取精确数值，从 Tentacle 第一个 point release 起支持。</p><h2 id="未来规划" tabindex="-1">未来规划 <a class="header-anchor" href="#未来规划" aria-label="Permalink to &quot;未来规划&quot;">​</a></h2><h3 id="升级时自动暂停追踪" tabindex="-1">升级时自动暂停追踪 <a class="header-anchor" href="#升级时自动暂停追踪" aria-label="Permalink to &quot;升级时自动暂停追踪&quot;">​</a></h3><p>Ceph 升级（包括滚动升级，逐个更新 daemon）期间会产生预期停机。未来版本将支持：升级开始时<strong>自动禁用</strong>可用性追踪，升级完成后<strong>自动重新启用</strong>。</p><p>注意：仅对原本已启用该功能的集群生效，不会主动为用户开启。</p><h3 id="接入-telemetry-可视化历史趋势" tabindex="-1">接入 Telemetry 可视化历史趋势 <a class="header-anchor" href="#接入-telemetry-可视化历史趋势" aria-label="Permalink to &quot;接入 Telemetry 可视化历史趋势&quot;">​</a></h3><p>当前功能可追踪累计可用性，但无法展示评分随时间的变化趋势。未来将把 score 数据上报至 telemetry，用户可据此可视化可用性评分的历史演变。</p><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li>官方文档：可用于启用功能并进行试用</li><li>Trello 看板及 CDS Reef 会议记录：可了解功能演进历史</li></ul><h2 id="行动呼吁" tabindex="-1">行动呼吁 <a class="header-anchor" href="#行动呼吁" aria-label="Permalink to &quot;行动呼吁&quot;">​</a></h2><ul><li>欢迎在上游社区 Slack 或邮件列表提供反馈</li><li>团队正在寻求<strong>大规模测试</strong>的合作方，欢迎启用该功能并反馈实际可用性评分数据</li></ul>',45)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
